func TestFilterStaleWorkbooks(t *testing.T) {
	now := time.Date(2026, 6, 25, 12, 0, 0, 0, time.UTC)
	fmtT := func(d time.Time) string { return d.Format(time.RFC3339) }

	old1 := staleWorkbook{Name: "Old One", Path: "/a", OwnerID: "m1", UpdatedAt: fmtT(now.AddDate(0, 0, -100))}
	old2 := staleWorkbook{Name: "Old Two", Path: "/b", OwnerID: "m2", UpdatedAt: fmtT(now.AddDate(0, 0, -45))}
	recent := staleWorkbook{Name: "Recent", Path: "/c", OwnerID: "m3", UpdatedAt: fmtT(now.AddDate(0, 0, -5))}
	all := []staleWorkbook{recent, old2, old1}

	t.Run("days 30 returns the two old ones, excludes recent", func(t *testing.T) {
		got := filterStaleWorkbooks(all, 30, now)
		if len(got) != 2 {
			t.Fatalf("expected 2 stale workbooks, got %d: %+v", len(got), got)
		}
		// Sorted by daysSince desc: Old One (100) then Old Two (45).
		if got[0].Name != "Old One" || got[1].Name != "Old Two" {
			t.Errorf("wrong order/contents: %+v", got)
		}
		for _, r := range got {
			if r.Name == "Recent" {
				t.Errorf("recent workbook should be excluded")
			}
		}
	})

	t.Run("days 9999 returns none", func(t *testing.T) {
		got := filterStaleWorkbooks(all, 9999, now)
		if len(got) != 0 {
			t.Errorf("expected 0 with --days 9999, got %d: %+v", len(got), got)
		}
	})

	t.Run("unparseable timestamps are skipped", func(t *testing.T) {
		got := filterStaleWorkbooks([]staleWorkbook{{Name: "Bad", UpdatedAt: "not-a-date"}}, 1, now)
		if len(got) != 0 {
			t.Errorf("expected unparseable row to be skipped, got %+v", got)
		}
	})
}
